package com.yihe.framework.ehr;
import java.util.*;import static com.yihe.framework.ehr.EhrAccess.*;import static com.yihe.framework.ehr.EhrService.*;
@SuppressWarnings("unchecked") public class ChronicScreeningChecks {
 static void check(String n,boolean v){if(!v)throw new AssertionError(n);System.out.println("PASS "+n);}static void reject(String n,Runnable fn){try{fn.run();throw new AssertionError(n);}catch(EhrException e){check(n,e.status==503);}}
 static Map<String,Object> output(Map<String,Object> model){List<Map<String,Object>> evidence=(List<Map<String,Object>>)model.get("evidence");List<Object> factors=new ArrayList<>();boolean any=false;for(String factor:ChronicScreening.FACTORS){String id=null;for(Map<String,Object> e:evidence)if("observation".equals(e.get("kind"))&&ChronicScreening.relevant(factor,e)){id=str(e.get("id"));break;}boolean assessed=id!=null;any|=assessed;factors.add(map("factor",factor,"level",assessed?"low":"unknown","data_status",assessed?"assessed":"insufficient","evidence_ids",assessed?Arrays.asList(id):new ArrayList<>(),"analysis","隔离测试，基于已提供检查数据整理待医生核实的慢性病风险线索，不直接确诊。","history_analysis","无可比历史，不编造变化。","missing_data",Arrays.asList("需核实病史与检查适用性"),"recommendations",Arrays.asList("按原件与实际情况补充资料")));}return map("schema_version",ChronicScreening.FORMAT,"subject_ref",model.get("subject_ref"),"summary","隔离慢病初筛流程测试。","suggested_risk",any?"low":"unknown","risk_rationale","仅基于已提供指标；未评项目不默认低风险。","factors",factors,"history_analysis","未提供可比历史。","recommendations",Arrays.asList("核对原报告与重复测量"),"doctor_attention",Arrays.asList("单次异常不等于确诊"),"limitations",Arrays.asList("缺少生活方式及相关病史"));}
 public static void main(String[]args){Map<String,Object> source=map("name","测试职工","code","TEST-PRIVATE-01","birth","1991-01-02","age",35,"sex","男","job","采煤工","exposure","煤尘","healthContext",map("smoking","未询问","medicalHistory","未明确诊断，原报告记录血压偏高"),"reports",Arrays.asList(map("id",id(),"revision",1,"examDate","2021-04-05","reviewStatus","needs_review","items",Arrays.asList(map("id",id(),"name","收缩压","value","158","unit","mmHg","referenceRange","90-140","abnormal","↑","page",2),map("id",id(),"name","BMI","value","31.8","unit","kg/m²","abnormal","↑","page",3)),"conclusions",new ArrayList<>(),"advice",new ArrayList<>())));
  OccupationalScreening.Input input=ChronicScreening.prepare(source,"SUB-CHRONIC-TEST");String serialized=OccupationalScreeningChecks.encode(input.model);check("chronic_input_has_temp_subject_not_identity",!serialized.contains("测试职工")&&!serialized.contains("TEST-PRIVATE-01")&&!serialized.contains("1991-01-02"));check("chronic_input_omits_calendar_date",!serialized.contains("2021-04-05")&&!serialized.contains("examDate"));check("health_context_and_missing_items_explicit",serialized.contains("HC-smoking")&&serialized.contains("missingHealthContext")&&serialized.contains("familyHistory"));check("no_occupational_measurement_gap_confused_with_chronic",!serialized.contains("missingExposureMeasurements"));Map<String,Object> out=output(input.model),r=ChronicScreening.parse(OccupationalScreeningChecks.encode(out),input);check("five_independent_chronic_domains",((Map<?,?>)r.get("domains")).size()==5);check("absent_glucose_not_default_low","unknown".equals(((Map<?,?>)((Map<?,?>)r.get("domains")).get("diabetes")).get("level")));check("no_fake_probability_or_score",r.get("riskScore")==null&&r.containsKey("scoreNote"));check("source_page_preserved",OccupationalScreeningChecks.encode(r.get("evidence")).contains("\"page\":2"));check("empty_original_advice_does_not_block",ChronicScreening.plain(r).contains("待医生审核"));
  Map<String,Object> diabetes=(Map<String,Object>)((List<?>)out.get("factors")).get(1);diabetes.put("data_status","assessed");diabetes.put("level","low");diabetes.put("evidence_ids",Arrays.asList("R1-OBS-1"));reject("blood_pressure_not_glucose_evidence",()->ChronicScreening.parse(OccupationalScreeningChecks.encode(out),input));diabetes.put("data_status","insufficient");reject("insufficient_data_cannot_be_low",()->ChronicScreening.parse(OccupationalScreeningChecks.encode(out),input));diabetes.put("level","unknown");diabetes.put("evidence_ids",Arrays.asList("FAKE-ID"));reject("invented_reference_rejected",()->ChronicScreening.parse(OccupationalScreeningChecks.encode(out),input));diabetes.put("evidence_ids",new ArrayList<>());out.put("subject_ref","SUB-OTHER-0001");reject("wrong_subject_result_rejected",()->ChronicScreening.parse(OccupationalScreeningChecks.encode(out),input));out.put("subject_ref",input.model.get("subject_ref"));((Map<String,Object>)((List<?>)out.get("factors")).get(0)).put("level","high");reject("overall_not_lower_than_highest_factor",()->ChronicScreening.parse(OccupationalScreeningChecks.encode(out),input));check("english_hospital_glucose_alias",ChronicScreening.relevant("diabetes",map("name","GLU","kind","observation")));check("english_hospital_lipid_alias",ChronicScreening.relevant("lipids",map("name","TG","kind","observation")));reject("plain_model_text_not_completed_json",()->ChronicScreening.parse("建议进一步复查",input));
 }
}
